 *
 * What genuinely differs between fields stays out of this class and lives at each call site in
 * [SettingsState] instead: the network call itself and the failure copy.
 */
private class OptimisticWrite<T>(
    initial: T,
) {
    private val sequence = Sequencer()

    /** What the control shows for this field. */
    var value: T by mutableStateOf(initial)
        private set

    /**
     * The last value the server is actually **known** to hold for this field — from a successful
     * write of this field ([onSuccess]) or a successful [SettingsState.load] ([adoptLoad]) — `null`
     * until one of those has actually happened, never a guess.
     */
    var confirmed: T? = null
        private set

    private var savingCalls: Int by mutableStateOf(0)

    /** True while at least one write of this field is in flight. */
    val isSaving: Boolean
        get() = savingCalls > 0

    /**
     * How many writes of this field have succeeded, ever — not just the newest. A load that began
     * before this count last advanced has been overtaken for this field: the server's value changed
     * after that load asked, so the load's answer must not become this field's [confirmed] even if
     * it is otherwise still the newest load in flight. See [SettingsState.load].
     */
    var succeededWriteCount = 0
        private set

    /**
     * Starts a new optimistic write of this field: shows [optimistic] immediately and returns the
     * token the caller must hold onto and pass back to [onSuccess] or [onFailure]. Callers increment
     * around a `try`/`finally` calling [end] in the `finally`, mirroring [SettingsState.isLoading]'s
     * own reference-count shape.
     */
    fun begin(optimistic: T): Int {
        val token = sequence.next()
        value = optimistic
        savingCalls++
        return token
    }

    /** Ends the in-flight bookkeeping a matching [begin] started — always call this from the caller's own `finally`. */
    fun end() {
        savingCalls--
    }

    /**
     * Records that the write named by [token] succeeded with [serverValue]. [confirmed] always
     * adopts it — true information about the server the moment it landed, regardless of whether
     * [token] is still the newest write of this field (see [SettingsState]'s class KDoc on why
     * [kotlinx.coroutines.sync.Mutex]-serialised sends make that safe). [value] only follows along
     * while [token] is still current; the return value tells the caller whether that happened, so it
     * knows whether to also clear its own shared `loadFailed`.
     */
    fun onSuccess(
        token: Int,
        serverValue: T,
    ): Boolean {
        succeededWriteCount++
        confirmed = serverValue
        val current = sequence.isCurrent(token)
        if (current) value = serverValue
        return current
    }

    /**
     * Records that the write named by [token] failed, and reports which of three things happened —
     * see [WriteFailureOutcome]'s own cases. A [WriteFailureOutcome.STALE] result changes nothing at
     * all: the newer write that superseded [token] already owns the screen and already answered (or
     * will answer) for this field, so this failure is not news.
     */
    fun onFailure(token: Int): WriteFailureOutcome {
        if (!sequence.isCurrent(token)) return WriteFailureOutcome.STALE
        val confirmedNow = confirmed
        return if (confirmedNow != null) {
            value = confirmedNow
            WriteFailureOutcome.REVERTED_TO_CONFIRMED
        } else {
            WriteFailureOutcome.NOTHING_CONFIRMED
        }
    }

    /**
     * Adopts [serverValue] as this field's own answer to a successful [SettingsState.load]:
     * [confirmed] unconditionally (the caller only calls this once it has already checked no write
     * of this field has succeeded since the load began), [value] too but only while no write of this
     * field is currently in flight — a pending optimistic choice must not be clobbered by a read
     * that was already stale the moment it was issued, even when that read's answer is still good
     * enough to become the new confirmed value.
     */
    fun adoptLoad(serverValue: T) {
        confirmed = serverValue
        if (!isSaving) value = serverValue
    }
}

/**
    /**
     * False until [load] has answered once, success or failure. The screen draws a skeleton until then:
     * [displayUnit] reads kilograms before the answer, and a user on pounds saw it flip (KAN-575 fix
     * round 4).
     */
    var hasLoaded: Boolean by mutableStateOf(false)
        private set

    /** True while at least one [chooseUnit] or [chooseSessionView] call is in flight. */
    val isSaving: Boolean
        get() = unitWrite.isSaving || viewWrite.isSaving

    /**
     * True once the latest [load] has failed, or the latest [chooseUnit] failed with nothing yet
     * confirmed to fall back on — either way the screen offers the same in-place retry, which is just
     * [load] again.
     */
    var loadFailed: Boolean by mutableStateOf(false)
        private set

    /** Advanced by every [load] call; a response is applied only while it is still the newest one. */
    private val loadSeq = Sequencer()

    /** Serialises every [chooseUnit] and [chooseSessionView] send — see the class KDoc. */
    private val sendMutex = Mutex()

    /** Reads the stored preferences, so the control opens on what the server actually holds. */
    suspend fun load() {
        val thisLoadSeq = loadSeq.next()
        val unitWritesBeforeThisLoad = unitWrite.succeededWriteCount
        val viewWritesBeforeThisLoad = viewWrite.succeededWriteCount
        loadingCalls++
        try {
            val result = runCatching { api.getPreferences() }
            // Computed once, right after the suspending call above returns and before either branch
            // below runs — there is no suspension point in between, so this cannot go stale by the
            // time either branch reads it. A write that succeeded after this load began already told
            // us the truth about the server, so this load's own answer — success *or* failure — is
            // stale and must not be treated as new information.
            val noUnitWriteSucceededSinceThisLoadBegan = unitWrite.succeededWriteCount == unitWritesBeforeThisLoad
            val noViewWriteSucceededSinceThisLoadBegan = viewWrite.succeededWriteCount == viewWritesBeforeThisLoad
            val current = loadSeq.isCurrent(thisLoadSeq)
            val noWriteSucceeded = noUnitWriteSucceededSinceThisLoadBegan && noViewWriteSucceededSinceThisLoadBegan
            result
                .onSuccess {
                    if (current && noWriteSucceeded) loadFailed = false
                    if (current && noUnitWriteSucceededSinceThisLoadBegan) unitWrite.adoptLoad(it.displayUnit)
                    if (current && noViewWriteSucceededSinceThisLoadBegan) viewWrite.adoptLoad(it.sessionView)
                }.onFailureNotCancelled {
                    if (current && noWriteSucceeded) {
                        loadFailed = true
                        notifications.failure(it.message ?: "Could not load your settings.")
                    }
                }
        } finally {
            loadingCalls--
            hasLoaded = true
        }
    }

    /**
     * Stores [unit] as the display preference, adopting whatever the server answers is now in
     * force, and putting the control back to its last confirmed value if the write is refused — see
     * the class KDoc for exactly when each of those happens.
     */
    suspend fun chooseUnit(unit: WeightUnit) {
        val token = unitWrite.begin(unit)
        try {
            runCatching { sendMutex.withLock { api.updatePreferences(displayUnit = unit) } }
                .onSuccess {
                    if (unitWrite.onSuccess(token, it.displayUnit)) loadFailed = false
                }.onFailureNotCancelled {
                    when (unitWrite.onFailure(token)) {
                        WriteFailureOutcome.STALE -> {
                            Unit
                        }

                        WriteFailureOutcome.REVERTED_TO_CONFIRMED -> {
                            notifications.failure(it.message ?: "Could not save your weight unit.")
                        }

                        WriteFailureOutcome.NOTHING_CONFIRMED -> {
                            // Nothing has ever been confirmed: reverting would invent a value the
                            // server never sent. Leave the control where it is and offer the same
                            // retry path a failed load does, so the user can re-sync.
                            loadFailed = true
                            notifications.failure(it.message ?: "Could not save your weight unit.")
                        }
                    }
                }
        } finally {
            unitWrite.end()
        }
    }

